HHAuto_ToolTips.es['seasonFocusSelector'] = { version: "8.5.0", elementText: "Objetivo de temporada", tooltip: "<span class=\"tipHint\">Útil para las incursiones de amor.</span><p>Elige en qué deben centrarse los combates de temporada:</p><ul><li><b>Todos los combates</b> &mdash; sin restricción, combate siempre.</li><li><b>Chica de evento</b> &mdash; combate sólo mientras falten fragmentos de la chica; omite los rivales que sólo dan fragmentos de skin.</li><li><b>Chica + skin</b> &mdash; combate mientras aún se pueda conseguir la chica o su skin.</li></ul><p>La interacción con el Nivel máx. la controla el interruptor <b>NM estricto</b>. La detección de skins usa los datos de incursión leídos en la pantalla de incursiones.</p>"};
HHAuto_ToolTips.es['buyLoveRaidCombat'] = { version: "7.25.6", elementText: "Comprar comb. para incursión", tooltip: "<p style = 'color:red'>/ !\\ Función que gasta Kobans /!\\<br>("+HHAuto_ToolTips.es['spendKobans0'].elementText+" debe estar activado)</p > Si habilitado: <br>Compra puntos de combate durante un evento de Incursión de Amor (si no se baja del valor del banco de Kobans). Esto ignora el umbral si hay fragmentos de la chica de evento disponibles."};
